    fun of(theme: String, dark: Boolean): ColorScheme = when (theme) {
        "default" -> if (dark) defaultDark else defaultLight
        "claude" -> if (dark) claudeDark else claudeLight
        "chatgpt" -> if (dark) chatgptDark else chatgptLight
        "gemini" -> if (dark) geminiDark else geminiLight
        "perplexity" -> if (dark) perplexityDark else perplexityLight
        "mistral" -> if (dark) mistralDark else mistralLight
        "purple" -> if (dark) purpleDark else purpleLight
        else -> throw IllegalArgumentException("Unknown Gremorie theme: $theme")
    }
}
